package com.drogaria.backend.dto;
import jakarta.validation.constraints.NotBlank; import jakarta.validation.constraints.NotNull;
public class EnderecoRequest { @NotBlank private String rua; @NotBlank private String numero; @NotBlank private String bairro; @NotBlank private String cidade; @NotBlank private String estado; @NotBlank private String cep; @NotNull private Integer idCliente; public String getRua(){return rua;} public void setRua(String v){rua=v;} public String getNumero(){return numero;} public void setNumero(String v){numero=v;} public String getBairro(){return bairro;} public void setBairro(String v){bairro=v;} public String getCidade(){return cidade;} public void setCidade(String v){cidade=v;} public String getEstado(){return estado;} public void setEstado(String v){estado=v;} public String getCep(){return cep;} public void setCep(String v){cep=v;} public Integer getIdCliente(){return idCliente;} public void setIdCliente(Integer v){idCliente=v;} }